 function hitBlock(b){if(b.bump>0)return;b.bump=.18;if(b.kind==='question'&&!b.used){b.used=true;coins++;score+=200;updateHud();sound(900,.1,'sine');burst(b.x+8,b.y-5,'#ffdb59',8);announce('+200  ●')}else{sound(170,.08,'square');burst(b.x+8,b.y,'#be7045',5)}}
